_CORE_SRC = '# Action: "[(from_node, to_node, count), ...]" (a list of integer tuples).\n# Payout: "served_i = capacity_i * demand / max(total_capacity, demand)",\n# where "capacity_i = drones_i * drone_capacity" and drone_capacity = 5.\n# Cost: "UPKEEP = 2.0" per drone away from its own base after movement.\n# Each drone moves at most one edge per turn, using start-of-turn availability.\n\nimport heapq\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 100\nDRONE_CAPACITY = 5\nUPKEEP = 2.0\n\n\ndef served(own, opponent, demand):\n    capacity = DRONE_CAPACITY * own\n    denominator = max(DRONE_CAPACITY * (own + opponent), demand)\n    return capacity * demand / denominator if denominator > 0.0 else 0.0\n\n\ndef revenue_difference(own, opponent, demand):\n    return served(own, opponent, demand) - served(opponent, own, demand)\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        adjacency[a].append(b)\n        adjacency[b].append(a)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        distance = [-1] * n\n        distance[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for neighbor in adjacency[node]:\n                if distance[neighbor] < 0:\n                    distance[neighbor] = distance[node] + 1\n                    queue.append(neighbor)\n        distances.append(distance)\n\n    next_hop = [[-1] * n for _ in range(n)]\n    for source in range(n):\n        for target in range(n):\n            if distances[source][target] > 0:\n                for neighbor in adjacency[source]:\n                    if distances[neighbor][target] == distances[source][target] - 1:\n                        next_hop[source][target] = neighbor\n                        break\n    return adjacency, distances, next_hop\n\n\ndef legal_action(have, want, adjacency, distances, next_hop):\n    """Match closest surpluses first, then validate against original availability."""\n    n = len(have)\n    surplus = [max(0, have[i] - want[i]) for i in range(n)]\n    deficit = [max(0, want[i] - have[i]) for i in range(n)]\n    pairs = sorted(\n        (distances[s][t], s, t)\n        for s in range(n) if surplus[s]\n        for t in range(n) if deficit[t] and distances[s][t] > 0\n    )\n    moves = {}\n    for _, source, target in pairs:\n        count = min(surplus[source], deficit[target])\n        if count <= 0:\n            continue\n        hop = next_hop[source][target]\n        if hop < 0:\n            continue\n        surplus[source] -= count\n        deficit[target] -= count\n        key = (source, hop)\n        moves[key] = moves.get(key, 0) + count\n\n    available = list(have)\n    result = []\n    for (source, destination), count in sorted(moves.items()):\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if destination not in adjacency[source]:\n            continue\n        count = min(int(count), int(available[source]))\n        if count > 0:\n            available[source] -= count\n            result.append((int(source), int(destination), int(count)))\n    return result\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_key = None\n        self.map_data = None\n        self.previous_target = None\n        self.previous_turn = None\n        self.bad_reports = 0\n        self.conservative = False\n\n    def plan(self, obs, deadline):\n        n = int(obs["n_nodes"])\n        base = int(obs["player_base"])\n        enemy_base = int(obs["opponent_base"])\n        have = list(obs["player_drones"])\n        opponent = list(obs["opponent_drones"])\n        forecast = obs["demand_forecast"]\n        turn = int(obs.get("turn", 0))\n        _, distances, _ = self.map_data\n\n        # The finite planning horizon avoids treating an uncertain forecast tail\n        # as a guaranteed hundred-turn annuity. All travel upkeep is charged.\n        horizon = min(12, max(0, N_TURNS - turn))\n        if horizon <= 0:\n            return have\n        demands = []\n        for node in range(n):\n            window = list(forecast[node])\n            if not window:\n                window = [0.0]\n            # Beyond the exact forecast, hold its recent mean, not a spike.\n            tail = sum(window[-3:]) / len(window[-3:])\n            demands.append([\n                float(window[k]) if k < len(window) else tail\n                for k in range(horizon)\n            ])\n\n        targets = [0] * n\n        remaining = list(have)\n        previous = self.previous_target\n        sticky = (\n            previous is not None\n            and self.previous_turn == turn - 1\n            and not self.conservative\n        )\n        marginal_cache = {}\n\n        def gain(source, target, count):\n            distance = distances[source][target]\n            if distance < 0:\n                return -1.0e30\n            delay = max(0, distance - 1)\n            if delay >= horizon:\n                return -1.0e30\n            key = (target, count, delay)\n            value = marginal_cache.get(key)\n            if value is None:\n                enemy = opponent[target]\n                value = 0.0\n                for k in range(delay, horizon):\n                    demand = demands[target][k]\n                    value += (\n                        revenue_difference(count + 1, enemy, demand)\n                        - revenue_difference(count, enemy, demand)\n                        - UPKEEP\n                    )\n                marginal_cache[key] = value\n\n            # Compare deployment with returning this particular drone home.\n            # A trip of d edges has d-1 paid transit turns before arrival.\n            return_delay = max(0, distances[source][base] - 1)\n            value -= UPKEEP * delay\n            value += UPKEEP * min(horizon, return_delay)\n\n            # Small hysteresis; never let it make a truly losing deployment\n            # look profitable relative to returning home.\n            if value > 0.0:\n                if source == target:\n                    value += 0.18 * (horizon - delay)\n                if sticky and count < previous[target]:\n                    value += 0.12 * (horizon - delay)\n            return value\n\n        heap = []\n        for source in range(n):\n            if remaining[source] <= 0:\n                continue\n            for target in range(n):\n                if target == base or target == enemy_base:\n                    continue\n                value = gain(source, target, 0)\n                heapq.heappush(heap, (-value, source, target, 0))\n\n        # Heap entries become stale only when their destination receives a unit.\n        # Concavity means stale entries are upper bounds, so lazy refresh is safe.\n        while heap and time.perf_counter() < deadline:\n            negative, source, target, version = heapq.heappop(heap)\n            if remaining[source] <= 0:\n                continue\n            if version != targets[target]:\n                value = gain(source, target, targets[target])\n                heapq.heappush(\n                    heap, (-value, source, target, targets[target])\n                )\n                continue\n            if -negative <= 0.0:\n                break\n            targets[target] += 1\n            remaining[source] -= 1\n            if remaining[source] > 0:\n                value = gain(source, target, targets[target])\n                heapq.heappush(\n                    heap, (-value, source, target, targets[target])\n                )\n\n        # Unassigned units are spare capacity: home is their cost-free target.\n        targets[base] += sum(remaining)\n        return targets\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n\n        edges = obs.get("edges", [])\n        key = (n, tuple((int(a), int(b)) for a, b in edges))\n        if self.map_key != key:\n            self.map_data = preprocess_map(n, edges)\n            self.map_key = key\n            self.previous_target = None\n\n        bad = (\n            not obs.get("action_format_correct_last_turn", True)\n            or int(obs.get("n_invalid_actions_last_turn", 0)) > 0\n        )\n        if bad:\n            self.bad_reports += 1\n        if self.bad_reports >= 2:\n            self.conservative = True\n\n        have = list(obs.get("player_drones", []))\n        if len(have) != n or not sum(have):\n            return []\n\n        # The planner always completes a conserved allocation, even if its\n        # deadline interrupts the heap. Movement itself never chains arrivals.\n        target = self.plan(obs, deadline)\n        adjacency, distances, next_hop = self.map_data\n        action = legal_action(have, target, adjacency, distances, next_hop)\n        self.previous_target = list(target)\n        self.previous_turn = int(obs.get("turn", 0))\n        return action\n'
